/* eslint-disable */
// ArabUT Coins Pricing v2.3
// Manual and scheduled runs both APPLY directly to Laravel.
// Provider secrets are read by the probe nodes from environment variables.
// Keep every non-secret business/probe value here so a future settings UI can
// replace this object without changing the rest of the workflow.

const alphabet = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

function ulid() {
  let time = Date.now();
  let timestamp = '';
  for (let index = 0; index < 10; index += 1) {
    timestamp = alphabet[time % 32] + timestamp;
    time = Math.floor(time / 32);
  }

  let random = '';
  for (let index = 0; index < 16; index += 1) {
    random += alphabet[Math.floor(Math.random() * alphabet.length)];
  }

  return timestamp + random;
}

function generatedAt() {
  return new Date().toISOString().replace(/\.(\d{3})Z$/, '.$1000Z');
}

// `increment` is NOT a free choice. Laravel rejects the whole run unless it
// equals the live Coins rounding unit - the grain a customer may actually buy,
// editable from the admin - and unless minimum and the three maxima match the
// active storefront settings exactly. The matching check lives in
// CoinsPricingRunRequest::validateLegalRanges(), and its 422 names both the
// expected range and the received one.
//
// Two things to know before changing it:
//   - The same three values are restated in "Validate Snapshot" as an
//     independent guard. Change both or the run fails its own validation.
//   - A finer grain multiplies every per-quantity loop here. At 5,000 the three
//     multiplier maps hold 8,373 entries between them. Laravel drops the
//     entries that only repeat the one before them before storing, so the wire
//     may stay dense; this workflow does not need to collapse it.
const legalRanges = {
  console_normal: { minimum: 50_000, maximum: 2_000_000, increment: 5_000 },
  console_fast: { minimum: 50_000, maximum: 20_000_000, increment: 5_000 },
  pc: { minimum: 50_000, maximum: 20_000_000, increment: 5_000 },
};

// 1M is the promotional, lowest-uplift point. Smaller orders keep a stronger
// operating contribution; larger orders receive a small guarantee/liquidity
// uplift. Values are basis points. These eleven anchors are now published
// as-is; Laravel interpolates between them at read time.
const quantityCommercialUpliftAnchorsBps = {
  50_000: 11_000,
  100_000: 10_600,
  150_000: 10_500,
  250_000: 10_300,
  500_000: 10_200,
  1_000_000: 10_000,
  2_000_000: 10_150,
  5_000_000: 10_250,
  10_000_000: 10_350,
  15_000_000: 10_400,
  20_000_000: 10_500,
};

const settings = {
  mode: 'apply',
  endpoint: 'https://store.arab-ut.com/api/automation/v1/pricing/coins/runs',

  // Provider secrets are read by the probe nodes from environment variables:
  // FFT_API_USER, FFT_API_KEY and UTT_API_KEY.
  providers: {
    fft: {
      baseUrl: 'https://futtransfer.top',
    },
    utt: {
      baseUrl: 'https://utautotransfer.com/api',
    },
  },

  legalRanges,
  tierCapsK: [1_000, 2_000, 5_000, 10_000, 15_000, 20_000],
  tierUpperBoundsK: [1_000, 2_000, 5_000, 10_000, 15_000],

  // Shared economics.
  effectiveUsdToSar: 3.85,
  smallOrderFeeHalalah: 300,
  discountDivisorBasisPoints: 10_000,
  quantityCommercialUpliftAnchorsBps,

  // Provider probes. There is no historical market floor/ceiling. Cycle uses
  // seller hint + exponential expansion + binary search. Targeted starts from
  // the provider's live distribution. Risk level matches fulfillment.
  probe: {
    transferRiskLevel: 10,
    maximumSupportedCoins: 20_000_000,
    providerTimeoutMs: 12_000,
    retryCount: 2,
    retryDelayMs: 500,

    cycleAmountCoins: {
      ps: 2_000_000,
      pc: 2_000_000,
    },
    cyclePricePrecisionUsdPer100K: 0.01,
    cycleFallbackStartUsdPer100K: 0.50,
    cycleExpansionMultiplier: 2,
    cycleMaximumExpansionSteps: 18,
    cycleConfirmationCalls: 2,
    cycleBacktrackSteps: 5,

    targetedPricePrecisionEurPer100K: 0.01,
    targetedMaximumCandidateTicks: 5_000,

    // Deliberately unconstrained theoretical receiver balance for UTT's
    // capacity prediction. UTT documents 999,999,999 as its default.
    uttPredictionStartCoins: 999_999_999,
  },

  // The formula keeps the current business economics. `marginDivisor` is the
  // historical divisor used by the existing workflow, not a literal margin %.
  groups: {
    console_normal: {
      marginDivisor: 0.80,
      operationalMarkupUsdPerM: 0.5,
      commissionUsdPerM: 1,
    },
    console_fast: {
      marginDivisor: 0.80,
      operationalMarkupUsdPerM: 0.5,
      commissionUsdPerM: 1,
    },
    pc: {
      marginDivisor: 0.65,
      operationalMarkupUsdPerM: 1.5,
      commissionUsdPerM: 2,
    },
  },

  // Owner decision: the provider quotes its live book, so a large rise or fall
  // is a real market move and must reach the storefront immediately. Damping
  // only delays correct prices. Set `enabled: true` to restore the softened
  // decrease behaviour described by the values below.
  stability: {
    enabled: false,
    holdDecreaseBelowBps: 100,
    applyDecreaseFractionBps: 5_000,
    maximumDecreasePerRunBps: 1_500,
  },
};

return [{
  json: {
    settings,
    eventId: ulid(),
    runId: ulid(),
    generatedAt: generatedAt(),
  },
}];

/* eslint-disable */
const config = $('Config').first().json;
const cfg = config.settings;
const provider = {
  ...cfg.providers.fft,
  apiUser: $env.FFT_API_USER,
  apiKey: $env.FFT_API_KEY,
};
const probe = cfg.probe;
const helpers = this.helpers;

if (!provider.apiUser || !provider.apiKey) {
  return [{
    json: {
      source: 'fft',
      failed: true,
      failureReason: 'FFT_API_USER or FFT_API_KEY is not configured',
      cycle: { ps: null, pc: null },
      targeted: { ps: [], pc: [] },
      audit: { calls: 0, errors: 0, retries: 0 },
    },
  }];
}

const audit = {
  calls: 0,
  errors: 0,
  retries: 0,
};

function parse(value) {
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      throw new Error('FFT returned a body that is not valid JSON');
    }
  }

  if (!value || typeof value !== 'object') {
    throw new Error('FFT returned an unexpected response type');
  }

  return value;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function round(value, places = 4) {
  const factor = 10 ** places;
  return Math.round(Number(value) * factor) / factor;
}

async function request(path, body) {
  let lastError = null;
  for (let attempt = 1; attempt <= probe.retryCount; attempt += 1) {
    audit.calls += 1;
    try {
      const response = await helpers.httpRequest({
        method: 'POST',
        url: `${provider.baseUrl}/${path}`,
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
          'User-Agent': 'ArabUT-Coins-Pricing/2.3',
        },
        body: JSON.stringify({
          ...body,
          apiUser: provider.apiUser,
          apiKey: provider.apiKey,
        }),
        timeout: probe.providerTimeoutMs,
      });

      const parsed = parse(response);
      // getMarketFeedback documents provider errors inside HTTP 200 bodies.
      // Do not reinterpret those errors as ordinary "no stock" observations.
      if (parsed.error) {
        throw new Error(`FFT ${path} returned error: ${parsed.error}`);
      }
      return parsed;
    } catch (error) {
      lastError = error;
      audit.errors += 1;
      if (attempt < probe.retryCount) {
        audit.retries += 1;
        await sleep(probe.retryDelayMs * attempt);
      }
    }
  }
  throw lastError ?? new Error(`FFT ${path} failed`);
}

function amountUnits(platform) {
  const coins = platform === 'PC'
    ? probe.cycleAmountCoins.pc
    : probe.cycleAmountCoins.ps;
  return Math.max(1, Math.ceil(Number(coins) / 100_000));
}

async function probeCycle(platform) {
  const step = Number(probe.cyclePricePrecisionUsdPer100K);
  if (!Number.isFinite(step) || step <= 0) {
    throw new Error('FFT cycle precision is invalid');
  }

  let hint = null;
  try {
    const seller = await request('getMarketFeedback', {
      role: 'seller',
      price: 0.1,
      platform,
      priceCurrency: 'USD',
      mode: 'cycle',
    });
    hint = Number(seller.avgFillPrice || seller.priceMin) || null;
  } catch {}

  const cache = new Map();
  const keyFor = (tick) => String(tick);
  const priceFor = (tick) => round(tick * step, 4);

  async function coverageAt(tick, bypassCache = false) {
    const key = keyFor(tick);
    if (!bypassCache && cache.has(key)) return cache.get(key);

    const response = await request('getMarketFeedback', {
      role: 'buyer',
      price: priceFor(tick),
      platform,
      priceCurrency: 'USD',
      amount: amountUnits(platform),
      mode: 'cycle',
    });
    // This used to be String(response.coverage || 'none'), so any answer the
    // code could not read collapsed to 'none' - which the ladder reads as
    // "price too low, go higher". A malformed response therefore pushed the
    // offer UP instead of stopping, and that is how a clearing price hundreds
    // of times above the market got recorded as real. Refuse to guess.
    const raw = response.coverage;
    if (typeof raw !== 'string' || raw.trim() === '') {
      throw new Error(
        `FFT ${platform} cycle returned no readable coverage at ` +
        `${priceFor(tick)} USD per 100K`,
      );
    }

    const value = raw.trim().toLowerCase();

    if (!bypassCache) cache.set(key, value);
    return value;
  }

  const minimumTick = 1;
  if ((await coverageAt(minimumTick)) === 'enough') {
    const confirmations = [];
    for (let index = 0; index < probe.cycleConfirmationCalls; index += 1) {
      confirmations.push(await coverageAt(minimumTick, true));
    }
    if (confirmations.every((value) => value === 'enough')) {
      const price = priceFor(minimumTick);
      return {
        platform,
        hintUsdPer100K: hint,
        clearingUsdPer100K: price,
        usdPerM: round(price * 10, 4),
        amountCoins: amountUnits(platform) * 100_000,
        probePoints: cache.size + confirmations.length,
      };
    }
  }

  let lowTick = minimumTick;
  let highTick = Math.max(
    lowTick + 1,
    Math.ceil(
      Number(hint || probe.cycleFallbackStartUsdPer100K) / step,
    ),
  );

  let highCoverage = await coverageAt(highTick);
  let expansions = 0;
  while (
    highCoverage !== 'enough' &&
    expansions < probe.cycleMaximumExpansionSteps
  ) {
    lowTick = highTick;
    highTick = Math.max(
      highTick + 1,
      Math.ceil(highTick * probe.cycleExpansionMultiplier),
    );
    highCoverage = await coverageAt(highTick);
    expansions += 1;
  }

  if (highCoverage !== 'enough') {
    return {
      platform,
      hintUsdPer100K: hint,
      clearingUsdPer100K: null,
      usdPerM: null,
      amountCoins: amountUnits(platform) * 100_000,
      probePoints: cache.size,
      failureReason: 'No FFT cycle clearing price was found',
    };
  }

  while (highTick - lowTick > 1) {
    const middleTick = Math.floor((lowTick + highTick) / 2);
    const coverage = await coverageAt(middleTick);
    if (coverage === 'enough') highTick = middleTick;
    else lowTick = middleTick;
  }

  // Backtrack a few fresh ticks in case one cached result was transient.
  for (let index = 0; index < probe.cycleBacktrackSteps; index += 1) {
    if (highTick <= minimumTick) break;
    const lowerCoverage = await coverageAt(highTick - 1, true);
    if (lowerCoverage === 'enough') highTick -= 1;
    else break;
  }

  const confirmations = [];
  for (let index = 0; index < probe.cycleConfirmationCalls; index += 1) {
    confirmations.push(await coverageAt(highTick, true));
  }
  if (!confirmations.every((value) => value === 'enough')) {
    return {
      platform,
      hintUsdPer100K: hint,
      clearingUsdPer100K: null,
      usdPerM: null,
      amountCoins: amountUnits(platform) * 100_000,
      probePoints: cache.size + confirmations.length,
      failureReason: 'FFT cycle clearing price did not pass confirmation',
    };
  }

  const price = priceFor(highTick);
  return {
    platform,
    hintUsdPer100K: hint,
    clearingUsdPer100K: price,
    usdPerM: round(price * 10, 4),
    amountCoins: amountUnits(platform) * 100_000,
    probePoints: cache.size + confirmations.length,
  };
}

function candidatePriceTicks(distribution, step) {
  const maximumTicks = Math.max(
    1,
    Number(probe.targetedMaximumCandidateTicks || 5_000),
  );
  const ticks = new Set();
  const epsilon = step / 1000;

  for (const bracket of distribution) {
    const from = Number(bracket.from);
    const to = Number(bracket.to);
    if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) continue;

    const first = Math.max(1, Math.ceil((from - epsilon) / step));
    const last = Math.max(first, Math.floor((to - epsilon) / step));
    const bracketTickCount = last - first + 1;

    // Fail closed before entering a pathological synchronous loop.
    if (bracketTickCount > maximumTicks) {
      throw new Error(
        `FFT targeted bracket requires ${bracketTickCount} ticks; limit is ${maximumTicks}`,
      );
    }

    for (let tick = first; tick <= last; tick += 1) {
      ticks.add(tick);
      if (ticks.size > maximumTicks) {
        throw new Error(
          `FFT targeted distribution exceeds ${maximumTicks} candidate ticks`,
        );
      }
    }
  }

  return [...ticks].sort((left, right) => left - right);
}

async function probeTargeted(platform) {
  const step = Number(probe.targetedPricePrecisionEurPer100K);
  if (!Number.isFinite(step) || step <= 0) {
    throw new Error('FFT targeted precision is invalid');
  }

  let feedback;
  try {
    feedback = await request('getMarketFeedback', {
      role: 'buyer',
      price: 0,
      platform,
      priceCurrency: 'EUR',
      mode: 'targeted',
    });
  } catch (error) {
    return {
      platform,
      distribution: [],
      tiers: [],
      failed: true,
      failureReason: 'FFT targeted distribution request failed',
    };
  }

  const distribution = (feedback.distribution || [])
    .map((entry) => ({
      from: Number(entry.from),
      to: Number(entry.to),
      stock: Number(entry.stock),
    }))
    .filter((entry) =>
      Number.isFinite(entry.from) &&
      Number.isFinite(entry.to) &&
      entry.to > entry.from &&
      entry.stock > 0,
    )
    .sort((left, right) => left.from - right.from);

  if (distribution.length === 0) {
    return {
      platform,
      distribution: [],
      tiers: cfg.tierCapsK.map((targetK) => ({
        targetK,
        covered: false,
        priceEurPer100K: null,
        maxK: 0,
      })),
      failed: false,
      failureReason: null,
      highestAvailable: null,
    };
  }

  let ticks;
  try {
    ticks = candidatePriceTicks(distribution, step);
  } catch (error) {
    return {
      platform,
      distribution: [],
      tiers: [],
      failed: true,
      failureReason: error.message || 'FFT targeted candidate generation failed',
    };
  }

  const cache = new Map();
  const priceFor = (tick) => round(tick * step, 4);

  async function maxKAt(index) {
    if (cache.has(index)) return cache.get(index);
    const price = priceFor(ticks[index]);
    // This operational endpoint is retained because it is already returning
    // live riskLevel-aware capacity in production, even though the public
    // Postman collection documents maxOrderPreviewAPI instead.
    const response = await request('calculateTargetedSnipe', {
      customerBalance: probe.maximumSupportedCoins,
      platform,
      maxPrice: price,
      riskLevel: probe.transferRiskLevel,
    });
    const maxK = Number(response.maxPossibleK);
    if (!Number.isFinite(maxK) || maxK < 0) {
      throw new Error(
        `FFT ${platform} targeted prediction omitted a valid maxPossibleK`,
      );
    }
    cache.set(index, maxK);
    return maxK;
  }

  async function firstCover(targetK) {
    if (ticks.length === 0) return null;
    const lastIndex = ticks.length - 1;
    if ((await maxKAt(lastIndex)) < targetK) return null;

    let low = 0;
    let high = lastIndex;
    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if ((await maxKAt(middle)) >= targetK) high = middle;
      else low = middle + 1;
    }

    return {
      targetK,
      covered: true,
      priceEurPer100K: priceFor(ticks[low]),
      maxK: await maxKAt(low),
    };
  }

  const tiers = [];
  for (const targetK of cfg.tierCapsK) {
    const covered = await firstCover(targetK);
    tiers.push(covered || {
      targetK,
      covered: false,
      priceEurPer100K: null,
      maxK: 0,
    });
  }

  const highestIndex = ticks.length - 1;
  const highestMaxK = highestIndex >= 0 ? await maxKAt(highestIndex) : 0;
  const cheapestHighest = highestMaxK > 0
    ? await firstCover(highestMaxK)
    : null;
  const highestAvailable = cheapestHighest
    ? {
        priceEurPer100K: cheapestHighest.priceEurPer100K,
        maxK: highestMaxK,
        capacityCoins: highestMaxK * 1_000,
      }
    : null;

  return {
    platform,
    distribution,
    tiers,
    highestAvailable,
    failed: false,
    failureReason: null,
    candidatePriceCount: ticks.length,
    probedPriceCount: cache.size,
    riskLevel: probe.transferRiskLevel,
    customerBalance: probe.maximumSupportedCoins,
  };
}

// Each probe must fail on its own. They run concurrently, so letting one throw
// out of Promise.all would reject all four - a PC cycle hiccup would wipe out a
// perfectly good PS cycle reading and stop the whole run, even though PC is no
// longer priced from the cycle at all. Contain each failure as a result.
async function settle(label, task) {
  try {
    return await task();
  } catch (error) {
    return {
      failed: true,
      failureReason: error.message || `${label} failed`,
    };
  }
}

let cyclePs;
let cyclePc;
let targetedPs;
let targetedPc;
try {
  [cyclePs, cyclePc, targetedPs, targetedPc] = await Promise.all([
    settle('FFT PS cycle', () => probeCycle('PS')),
    settle('FFT PC cycle', () => probeCycle('PC')),
    settle('FFT PS targeted', () => probeTargeted('PS')),
    settle('FFT PC targeted', () => probeTargeted('PC')),
  ]);
} catch (error) {
  return [{
    json: {
      source: 'fft',
      failed: true,
      failureReason: error.message || 'FFT probe failed',
      cycle: { ps: null, pc: null },
      targeted: { ps: [], pc: [] },
      audit,
    },
  }];
}

const psCycleOk = Number.isFinite(Number(cyclePs?.usdPerM));
const pcCycleOk = Number.isFinite(Number(cyclePc?.usdPerM));
const failed = !psCycleOk;

// A missing PC cycle is not a hard failure - PC is still priced from FFT
// targeted - but it must never be silent, because the PC cycle is the PC
// group's USD floor.
const warnings = [];
if (!pcCycleOk) {
  warnings.push(cyclePc?.failureReason || 'FFT PC cycle cost is unavailable');
}

return [{
  json: {
    source: 'fft',
    cycle: {
      ps: cyclePs,
      pc: cyclePc,
    },
    targeted: {
      ps: targetedPs,
      pc: targetedPc,
    },
    psCycleOk,
    pcCycleOk,
    warnings,
    failed,
    failureReason: failed
      ? (cyclePs?.failureReason || 'FFT PS cycle cost is unavailable')
      : null,
    audit,
  },
}];

/* eslint-disable */
const config = $('Config').first().json;
const cfg = config.settings;
const provider = {
  ...cfg.providers.utt,
  apiKey: $env.UTT_API_KEY,
};
const probe = cfg.probe;
const helpers = this.helpers;

if (!provider.apiKey) {
  return [{
    json: {
      source: 'utt',
      ratioEuroUsd: null,
      ps: { tiers: [], failed: true },
      pc: { tiers: [], failed: true },
      failed: true,
      failureReason: 'UTT_API_KEY is not configured',
      audit: { calls: 0, errors: 0, retries: 0 },
    },
  }];
}

const audit = {
  calls: 0,
  errors: 0,
  retries: 0,
};

function parse(value) {
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return {}; }
  }
  return value && typeof value === 'object' ? value : {};
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// n8n's Code-node sandbox doesn't expose URLSearchParams on every runtime.
// Build application/x-www-form-urlencoded bodies with standard primitives.
// UTT's stockSection is sent as its documented flat comma-separated string.
function formEncode(fields) {
  return Object.entries(fields)
    .filter(([, value]) => value !== undefined && value !== null)
    .map(([key, value]) =>
      `${encodeURIComponent(String(key))}=${encodeURIComponent(String(value))}`,
    )
    .join('&');
}

async function request(path, body) {
  let lastError = null;
  for (let attempt = 1; attempt <= probe.retryCount; attempt += 1) {
    audit.calls += 1;
    try {
      const encodedBody = formEncode({
        apiKey: provider.apiKey,
        ...body,
      });
      const response = await helpers.httpRequest({
        method: 'POST',
        url: `${provider.baseUrl}/${path}`,
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          Accept: 'application/json',
          'User-Agent': 'ArabUT-Coins-Pricing/2.1',
        },
        body: encodedBody,
        timeout: probe.providerTimeoutMs,
      });
      return parse(response);
    } catch (error) {
      lastError = error;
      audit.errors += 1;
      if (attempt < probe.retryCount) {
        audit.retries += 1;
        await sleep(probe.retryDelayMs * attempt);
      }
    }
  }
  throw lastError ?? new Error(`UTT ${path} failed`);
}

function round(value, places = 5) {
  const factor = 10 ** places;
  return Math.round(Number(value) * factor) / factor;
}

async function fetchPlatform(platform) {
  const sale = await request('getPublicSaleStocks', {
    platform: platform.toLowerCase(),
  });

  const ratioEuroUsd = Number(sale.ratioEuroUsd);
  if (!Number.isFinite(ratioEuroUsd) || ratioEuroUsd <= 0) {
    throw new Error(`UTT ${platform} EUR/USD ratio is missing`);
  }

  const stocks = (Array.isArray(sale.stocks) ? sale.stocks : [])
    .map((stock) => ({
      numberStock: String(stock.numberStock ?? '').trim(),
      price: Number(stock.price),
      // Preserve the provider's decimal representation in stockSection.
      priceToken: String(stock.price ?? '').trim(),
      averageCoinsAvailable: Number(stock.averageCoinsAvailable),
      totalCoinsStock: Number(stock.totalCoinsStock),
      accountsAvailable: Number(stock.accountsAvailable),
    }))
    // Owner-approved: do not impose a minimum average or stock quantity.
    // getMaxOrderPrediction is the authority on usable capacity.
    .filter((stock) =>
      stock.numberStock &&
      Number.isFinite(stock.price) &&
      stock.price > 0 &&
      stock.priceToken,
    )
    .sort((left, right) =>
      left.price - right.price ||
      left.numberStock.localeCompare(right.numberStock),
    );

  if (stocks.length === 0) {
    return {
      platform,
      ratioEuroUsd,
      tiers: cfg.tierCapsK.map((targetK) => ({
        targetK,
        covered: false,
        priceEurPer100K: null,
        maxTransferable: 0,
      })),
      failed: true,
      failureReason: `UTT ${platform} returned no eligible stocks`,
      stockCount: 0,
      priceLevelCount: 0,
    };
  }

  const priceLevels = [...new Set(stocks.map((stock) => stock.price))]
    .sort((left, right) => left - right);

  // Precompute the cumulative section count once. predictionAt() now slices an
  // already-built string array instead of filtering and mapping every stock on
  // every provider call.
  const stockSections = stocks.map(
    (stock) => `${stock.numberStock},${stock.priceToken}`,
  );
  const sectionCountByPriceLevel = [];
  let stockCursor = 0;

  for (const priceLevel of priceLevels) {
    while (
      stockCursor < stocks.length &&
      stocks[stockCursor].price <= priceLevel
    ) {
      stockCursor += 1;
    }
    sectionCountByPriceLevel.push(stockCursor);
  }

  const cache = new Map();

  async function predictionAt(index) {
    if (cache.has(index)) return cache.get(index);

    const price = priceLevels[index];
    const sections = stockSections.slice(
      0,
      sectionCountByPriceLevel[index],
    );

    const response = await request('getMaxOrderPrediction', {
      platform: platform.toLowerCase(),
      orderMethod: 'public',
      stockSection: sections.join(','),
      startCoins: probe.uttPredictionStartCoins,
    });

    const maxTransferable = Number(response.maxTransferable);
    if (!Number.isFinite(maxTransferable) || maxTransferable < 0) {
      throw new Error(
        `UTT ${platform} prediction omitted a valid maxTransferable`,
      );
    }

    const cardLimit = Number(response.orderCardLimit);
    const cardsRemaining = Number(response.orderCardsRemaining);
    const result = {
      price,
      maxTransferable,
      orderCardLimit: Number.isFinite(cardLimit) ? cardLimit : null,
      orderCardsRemaining:
        Number.isFinite(cardsRemaining) ? cardsRemaining : null,
      cooldownCount: Array.isArray(response.cooldowns)
        ? response.cooldowns.length
        : 0,
      sectionCount: sections.length,
    };

    cache.set(index, result);
    return result;
  }

  async function firstCover(targetCoins) {
    const lastIndex = priceLevels.length - 1;
    if ((await predictionAt(lastIndex)).maxTransferable < targetCoins) {
      return null;
    }

    let low = 0;
    let high = lastIndex;
    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if ((await predictionAt(middle)).maxTransferable >= targetCoins) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }

    // stockSection only grows as price rises, so the capacity sequence is
    // monotonic and the binary-search result is already the first cover.
    const prediction = await predictionAt(low);
    return {
      covered: true,
      priceEurPer100K: round(prediction.price, 4),
      maxTransferable: prediction.maxTransferable,
      orderCardLimit: prediction.orderCardLimit,
      orderCardsRemaining: prediction.orderCardsRemaining,
      cooldownCount: prediction.cooldownCount,
      sectionCount: prediction.sectionCount,
    };
  }

  const tiers = [];
  for (const targetK of cfg.tierCapsK) {
    const targetCoins = targetK * 1_000;
    const covered = await firstCover(targetCoins);
    tiers.push({
      targetK,
      targetCoins,
      ...(covered || {
        covered: false,
        priceEurPer100K: null,
        maxTransferable: 0,
        orderCardLimit: null,
        orderCardsRemaining: null,
        cooldownCount: 0,
        sectionCount: 0,
      }),
    });
  }

  const highestPrediction = await predictionAt(priceLevels.length - 1);
  const cheapestHighest = highestPrediction.maxTransferable > 0
    ? await firstCover(highestPrediction.maxTransferable)
    : null;
  const highestAvailable = cheapestHighest
    ? {
        priceEurPer100K: cheapestHighest.priceEurPer100K,
        maxTransferable: highestPrediction.maxTransferable,
        capacityCoins: highestPrediction.maxTransferable,
        orderCardLimit: cheapestHighest.orderCardLimit,
        orderCardsRemaining: cheapestHighest.orderCardsRemaining,
        cooldownCount: cheapestHighest.cooldownCount,
        sectionCount: cheapestHighest.sectionCount,
      }
    : null;

  return {
    platform,
    ratioEuroUsd,
    tiers,
    highestAvailable,
    failed: false,
    failureReason: null,
    stockCount: stocks.length,
    priceLevelCount: priceLevels.length,
    probedPriceLevelCount: cache.size,
    predictionStartCoins: probe.uttPredictionStartCoins,
    minimumAverageFilterApplied: false,
  };
}

let ps;
let pc;
try {
  [ps, pc] = await Promise.all([
    fetchPlatform('PS'),
    fetchPlatform('PC'),
  ]);
} catch (error) {
  return [{
    json: {
      source: 'utt',
      ratioEuroUsd: null,
      ps: { tiers: [], failed: true },
      pc: { tiers: [], failed: true },
      failed: true,
      failureReason: error.message || 'UTT probe failed',
      audit,
    },
  }];
}

const ratios = [ps.ratioEuroUsd, pc.ratioEuroUsd]
  .filter((value) => Number.isFinite(value) && value > 0);
const ratioEuroUsd = ratios.length
  ? round(ratios.reduce((sum, value) => sum + value, 0) / ratios.length, 5)
  : null;

const failed = !Number.isFinite(ratioEuroUsd) || (ps.failed && pc.failed);
return [{
  json: {
    source: 'utt',
    ratioEuroUsd,
    ps,
    pc,
    failed,
    failureReason: failed
      ? (ps.failureReason || pc.failureReason || 'UTT returned no usable observations')
      : null,
    audit,
  },
}];

/* eslint-disable */
const config = $('Config').first().json;
const settings = config.settings;
const supplierItems = $input.all().map((item) => item.json);
const fft = supplierItems.find((item) => item.source === 'fft');
const utt = supplierItems.find((item) => item.source === 'utt');

// Throwing routes every stop through the workflow's Error Trigger, which also
// catches the unexpected crashes an IF branch could never see. Nothing has
// been sent to Laravel at this point, so no pricing rule can have changed.
function fail(reason) {
  throw new Error(
    `Coins pricing stopped before any rule changed: ${reason} ` +
    `(runId ${config.runId ?? 'unknown'})`,
  );
}

function roundTenth(value) {
  return Math.round(Number(value) * 10) / 10;
}

function roundHalfUpBigInt(numerator, denominator) {
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;
  const half = denominator / 2n + (denominator % 2n);
  return remainder >= half ? quotient + 1n : quotient;
}


function roundToDisplayGrain(halalah) {
  return Number(roundHalfUpBigInt(BigInt(halalah), 10n)) * 10;
}

function positiveNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
}

if (!fft || !utt) {
  return fail('Supplier observations are incomplete');
}
if (!positiveNumber(fft.cycle?.ps?.usdPerM)) {
  return fail(fft.failureReason || 'FFT PS cycle cost is unavailable');
}
if (!positiveNumber(utt.ratioEuroUsd)) {
  return fail(utt.failureReason || 'UTT EUR/USD ratio is unavailable');
}

const ratioEuroUsd = Number(utt.ratioEuroUsd);
const tierCaps = settings.tierCapsK;

function tierEntry(container, targetK) {
  const tiers = container?.tiers;
  if (!Array.isArray(tiers)) return null;
  return tiers.find((entry) => Number(entry.targetK) === Number(targetK)) || null;
}

function fftTargetedCandidate(platform, targetK) {
  const entry = tierEntry(fft.targeted?.[platform], targetK);
  const price = positiveNumber(entry?.priceEurPer100K);
  if (!entry?.covered || price === null) return null;
  return {
    source: `fft_targeted_${platform}`,
    rawUsdPerM: price * 10 * ratioEuroUsd,
    providerPriceEurPer100K: price,
    providerCapacityCoins: Number(entry.maxK || 0) * 1_000,
  };
}

function uttCandidate(platform, targetK) {
  const entry = tierEntry(utt?.[platform], targetK);
  const price = positiveNumber(entry?.priceEurPer100K);
  if (!entry?.covered || price === null) return null;
  return {
    source: `utt_${platform}`,
    rawUsdPerM: price * 10 * ratioEuroUsd,
    providerPriceEurPer100K: price,
    providerCapacityCoins: Number(entry.maxTransferable || 0),
    orderCardLimit: entry.orderCardLimit ?? null,
    orderCardsRemaining: entry.orderCardsRemaining ?? null,
    cooldownCount: Number(entry.cooldownCount || 0),
  };
}

const cycleFloorSources = { ps: null, pc: null };

// Owner decision, from how the two supplier methods actually work: cycle has no
// cap on the number of transfers but each one moves a small amount, while
// targeted (surgical) moves large amounts but is capped at ten transfers, so a
// thin account burns its ten transfers on cheap cards and hits the limit. They
// are different products with different economics, which is why the two are
// mixed in fulfilment - cycle is used to build the balance up before switching.
// A cycle clearing price is therefore NOT a valid cost floor for a tier priced
// from targeted supply. PC is priced from FFT targeted and UTT alone.
const CYCLE_FLOOR_GROUPS = new Set(['ps']);

function cycleCost(platform) {
  if (!CYCLE_FLOOR_GROUPS.has(platform)) {
    cycleFloorSources[platform] = null;
    return null;
  }

  const cycle = positiveNumber(fft.cycle?.[platform]?.usdPerM);
  cycleFloorSources[platform] = cycle === null ? null : 'fft_cycle';

  return cycle;
}

function highestAvailableCandidates(platform) {
  const candidates = [];

  const fftHighest = fft.targeted?.[platform]?.highestAvailable;
  const fftPrice = positiveNumber(fftHighest?.priceEurPer100K);
  const fftCapacity = Number(fftHighest?.capacityCoins || 0);
  if (fftPrice !== null && fftCapacity > 0) {
    candidates.push({
      source: `fft_targeted_${platform}`,
      rawUsdPerM: fftPrice * 10 * ratioEuroUsd,
      providerPriceEurPer100K: fftPrice,
      providerCapacityCoins: fftCapacity,
    });
  }

  const uttHighest = utt?.[platform]?.highestAvailable;
  const uttPrice = positiveNumber(uttHighest?.priceEurPer100K);
  const uttCapacity = Number(uttHighest?.capacityCoins || uttHighest?.maxTransferable || 0);
  if (uttPrice !== null && uttCapacity > 0) {
    candidates.push({
      source: `utt_${platform}`,
      rawUsdPerM: uttPrice * 10 * ratioEuroUsd,
      providerPriceEurPer100K: uttPrice,
      providerCapacityCoins: uttCapacity,
      orderCardLimit: uttHighest.orderCardLimit ?? null,
      orderCardsRemaining: uttHighest.orderCardsRemaining ?? null,
      cooldownCount: Number(uttHighest.cooldownCount || 0),
    });
  }

  return candidates;
}

function buildPlatformCosts(platform) {
  const cycle = cycleCost(platform);
  const highestAvailable = highestAvailableCandidates(platform);
  const rows = [];
  let previous = null;

  for (const targetK of tierCaps) {
    const candidates = [
      fftTargetedCandidate(platform, targetK),
      uttCandidate(platform, targetK),
    ].filter(Boolean).sort((left, right) => left.rawUsdPerM - right.rawUsdPerM);

    let row;
    if (candidates.length > 0) {
      const selected = candidates[0];
      row = {
        targetK,
        directCoverage: true,
        fallback: false,
        selectedSource: selected.source,
        rawUsdPerM: roundTenth(selected.rawUsdPerM),
        candidates,
        fallbackFromTierK: null,
      };
    } else {
      // Owner-approved rule: if the requested tier has no direct coverage,
      // price it using the provider price that reaches the HIGHEST quantity
      // currently possible below that tier. This is more accurate than simply
      // reusing the previous named tier when a provider can reach, for example,
      // 8.2M even though the previous configured tier is 5M.
      const targetCoins = targetK * 1_000;
      const bestHighestAvailable = highestAvailable
        .filter((entry) =>
          entry.providerCapacityCoins > 0 &&
          entry.providerCapacityCoins < targetCoins,
        )
        .sort((left, right) =>
          right.providerCapacityCoins - left.providerCapacityCoins ||
          left.rawUsdPerM - right.rawUsdPerM,
        )[0] || null;

      if (bestHighestAvailable) {
        row = {
          targetK,
          directCoverage: false,
          fallback: true,
          selectedSource: `highest_available:${bestHighestAvailable.source}`,
          rawUsdPerM: roundTenth(bestHighestAvailable.rawUsdPerM),
          candidates: [],
          fallbackFromTierK: null,
          fallbackCapacityCoins: bestHighestAvailable.providerCapacityCoins,
          fallbackProviderPriceEurPer100K:
            bestHighestAvailable.providerPriceEurPer100K,
        };
      } else if (previous) {
        row = {
          targetK,
          directCoverage: false,
          fallback: true,
          selectedSource: `carry_forward:${previous.selectedSource}`,
          rawUsdPerM: previous.rawUsdPerM,
          candidates: [],
          fallbackFromTierK: previous.targetK,
          fallbackCapacityCoins: previous.fallbackCapacityCoins || previous.targetK * 1_000,
        };
      } else if (cycle !== null) {
        row = {
          targetK,
          directCoverage: false,
          fallback: true,
          selectedSource: `cycle_fallback_${platform}`,
          rawUsdPerM: roundTenth(cycle),
          candidates: [],
          fallbackFromTierK: null,
          fallbackCapacityCoins: null,
        };
      } else {
        return null;
      }
    }


    if (cycle !== null && row.rawUsdPerM < cycle) {
      row.rawUsdPerM = roundTenth(cycle);
      row.cycleFloorApplied = true;
    } else {
      row.cycleFloorApplied = false;
    }

    if (previous && row.rawUsdPerM < previous.rawUsdPerM) {
      row.rawUsdPerM = previous.rawUsdPerM;
      row.monotonicFloorApplied = true;
    } else {
      row.monotonicFloorApplied = false;
    }

    rows.push(row);
    previous = row;
  }

  return rows;
}

const psCosts = buildPlatformCosts('ps');
const pcCosts = buildPlatformCosts('pc');
if (!psCosts || !pcCosts) {
  return fail('A supplier cost basis could not be built for every platform');
}

function rateHalalahPerMillion(rawSupplierCostUsdPerM, groupName) {
  const group = settings.groups[groupName];
  const sellUsdPerM = (
    (Number(rawSupplierCostUsdPerM) + Number(group.operationalMarkupUsdPerM)) /
    Number(group.marginDivisor)
  ) + Number(group.commissionUsdPerM);

  const rate = Math.round(
    sellUsdPerM * Number(settings.effectiveUsdToSar) * 100,
  );
  if (!Number.isInteger(rate) || rate <= 0) {
    throw new Error(`${groupName} generated an invalid rate`);
  }
  return rate;
}

// Parse and sort the commercial uplift anchors once. The previous version
// repeated Object.entries(...).sort(...) for every legal quantity.
const multiplierAnchors = Object.entries(
  settings.quantityCommercialUpliftAnchorsBps,
)
  .map(([coins, bps]) => [Number(coins), Number(bps)])
  .sort((left, right) => left[0] - right[0]);

function interpolateMultiplierBps(quantity) {
  if (quantity <= multiplierAnchors[0][0]) {
    return Math.round(multiplierAnchors[0][1]);
  }

  const lastAnchor = multiplierAnchors[multiplierAnchors.length - 1];
  if (quantity >= lastAnchor[0]) {
    return Math.round(lastAnchor[1]);
  }

  for (let index = 1; index < multiplierAnchors.length; index += 1) {
    const [rightCoins, rightBps] = multiplierAnchors[index];
    if (quantity > rightCoins) continue;

    const [leftCoins, leftBps] = multiplierAnchors[index - 1];
    const progress = (quantity - leftCoins) / (rightCoins - leftCoins);
    return Math.round(leftBps + (rightBps - leftBps) * progress);
  }

  return 10_000;
}

// The anchors themselves are what gets published now. Laravel interpolates
// between them at read time against its own live quantity settings, so lowering
// the storefront minimum no longer needs a matching edit here.
//
// Every entry is load-bearing: Laravel drops repeats out of a threshold map but
// never out of an anchor table, because dropping one would move every price
// between the two survivors.
function anchorTable() {
  const table = {};

  for (const [coins, bps] of multiplierAnchors) {
    table[String(coins)] = Math.round(bps);
  }

  return table;
}

function tierRateFor(quantity, rates) {
  for (let index = 0; index < settings.tierUpperBoundsK.length; index += 1) {
    if (quantity <= settings.tierUpperBoundsK[index] * 1_000) {
      return rates[index];
    }
  }
  return rates[5];
}

// The published rule no longer carries an expansion to look a quantity up in,
// so the simulation interpolates the same anchors Laravel will.
//
// BEHAVIOUR CHANGE above 2M. The old code carried console_normal's terminal
// multiplier (10,150 at 2M) forward for the fast-delivery floor comparison.
// This follows the curve instead, which keeps rising to 10,500 at 20M, so a
// normal-derived floor binding for console_fast between 2M and 20M is up to
// 3.45% higher. Laravel's anchored curve does exactly the same, so the two
// still agree; the change is against the previous workflow, not between them.
function multiplierFor(rule, quantity) {
  const basisPoints = interpolateMultiplierBps(quantity);

  if (!Number.isInteger(basisPoints) || basisPoints <= 0) {
    throw new Error(`No multiplier covers ${rule.group} ${quantity}`);
  }

  return basisPoints;
}

function formulaSar(rule, quantity) {
  const rate = rule.group === 'console_normal'
    ? rule.flat_rate_halalah_per_million
    : tierRateFor(quantity, rule.tier_rates_halalah_per_million);
  const multiplier = multiplierFor(rule, quantity);
  const rateNumerator = BigInt(quantity) * BigInt(rate) * BigInt(multiplier);
  const feeGap = Math.max(0, 1_000_000 - quantity);
  const feeNumerator =
    BigInt(rule.service_fee_halalah) * BigInt(feeGap) * 10_000n;
  const denominator =
    1_000_000n * BigInt(rule.discount_divisor_basis_points);
  const rounded = roundHalfUpBigInt(rateNumerator + feeNumerator, denominator);
  return Math.max(roundToDisplayGrain(Number(rounded)), 100);
}

function percentageFloor(normalHalalah) {
  // Laravel's CoinsPriceCalculator::percentageFloor() reduces the normal price
  // to the 0.1-SAR grain BEFORE applying 105%. Applying 105% first and rounding
  // to the grain afterwards disagrees on 299 grain values - every normal price
  // ending in x.90 SAR on an odd riyal - and is always 10 halalah high. Mirror
  // Laravel exactly so the validated schedule is the schedule the storefront
  // actually serves.
  const grain = BigInt(normalHalalah) / 10n;
  return Number(roundHalfUpBigInt(grain * 105n, 100n)) * 10;
}

function perMillionFloor(normalHalalah, quantity) {
  return roundToDisplayGrain(Number(roundHalfUpBigInt(
    BigInt(normalHalalah) * 1_000_000n + BigInt(quantity) * 500n,
    1_000_000n,
  )));
}

function displayedSar(group, quantity, rules, useOverrides = true) {
  const rule = rules[group];
  const override = useOverrides
    ? rule.exact_overrides_halalah?.[String(quantity)]
    : null;
  if (Number.isInteger(override) && override > 0) return override;

  const base = formulaSar(rule, quantity);
  if (group !== 'console_fast') return base;

  // Laravel's fast floor uses the normal formula (not a normal exact override).
  const normal = formulaSar(rules.console_normal, quantity);
  return Math.max(
    base,
    percentageFloor(normal),
    perMillionFloor(normal, quantity),
    normal + 100,
  );
}

function smoothRate(previous, candidate) {
  if (!settings.stability.enabled || !Number.isInteger(previous) || previous <= 0) {
    return candidate;
  }
  if (candidate >= previous) return candidate;

  const dropBps = Math.round(((previous - candidate) / previous) * 10_000);
  if (dropBps < settings.stability.holdDecreaseBelowBps) return previous;

  const partial = previous - Math.round(
    (previous - candidate) * settings.stability.applyDecreaseFractionBps / 10_000,
  );
  const maximumDropFloor = Math.ceil(
    previous * (10_000 - settings.stability.maximumDecreasePerRunBps) / 10_000,
  );
  return Math.max(candidate, partial, maximumDropFloor);
}

const globalData = $getWorkflowStaticData('global');
const previousRates = globalData.coinsPricingV2?.lastSuccessfulRates ?? null;

const candidateRates = {
  console_normal: rateHalalahPerMillion(
    Number(fft.cycle.ps.usdPerM),
    'console_normal',
  ),
  console_fast: psCosts.map((row) =>
    rateHalalahPerMillion(row.rawUsdPerM, 'console_fast'),
  ),
  pc: pcCosts.map((row) =>
    rateHalalahPerMillion(row.rawUsdPerM, 'pc'),
  ),
};

const finalRates = {
  console_normal: smoothRate(
    previousRates?.console_normal,
    candidateRates.console_normal,
  ),
  console_fast: candidateRates.console_fast.map((rate, index) =>
    smoothRate(previousRates?.console_fast?.[index], rate),
  ),
  pc: candidateRates.pc.map((rate, index) =>
    smoothRate(previousRates?.pc?.[index], rate),
  ),
};

// Preserve non-decreasing rate tiers after independent smoothing.
for (const group of ['console_fast', 'pc']) {
  for (let index = 1; index < finalRates[group].length; index += 1) {
    finalRates[group][index] = Math.max(
      finalRates[group][index],
      finalRates[group][index - 1],
    );
  }
}

function commonRule(groupName) {
  return {
    version: 1,
    group: groupName,
    tier_upper_bounds_k: [...settings.tierUpperBoundsK],
    multiplier_anchors_basis_points: anchorTable(),
    service_fee_halalah: Math.round(settings.smallOrderFeeHalalah),
    discount_divisor_basis_points: Math.round(settings.discountDivisorBasisPoints),
    exact_overrides_halalah: {},
  };
}

const rules = {
  console_normal: {
    ...commonRule('console_normal'),
    flat_rate_halalah_per_million: finalRates.console_normal,
  },
  console_fast: {
    ...commonRule('console_fast'),
    tier_rates_halalah_per_million: finalRates.console_fast,
  },
  pc: {
    ...commonRule('pc'),
    tier_rates_halalah_per_million: finalRates.pc,
  },
};

// Whole-SAR rounding plus a promotional 1M point can occasionally make the
// next 10K cheaper. Add exact overrides only where needed to guarantee that
// every legal schedule is non-decreasing.
for (const group of ['console_normal', 'console_fast', 'pc']) {
  const range = settings.legalRanges[group];
  let previousPrice = null;
  for (
    let quantity = range.minimum;
    quantity <= range.maximum;
    quantity += range.increment
  ) {
    let price = displayedSar(group, quantity, rules, true);
    if (previousPrice !== null && price < previousPrice) {
      const safe = previousPrice;
      rules[group].exact_overrides_halalah[String(quantity)] = safe;
      price = safe;
    }
    previousPrice = price;
  }
}

const pricingAudit = {
  ratioEuroUsd,
  riskLevel: settings.probe.transferRiskLevel,
  cycleFloorSources,
  cycleFloorGroups: [...CYCLE_FLOOR_GROUPS],
  psCycleOk: fft.psCycleOk ?? null,
  pcCycleOk: fft.pcCycleOk ?? null,
  supplierWarnings: Array.isArray(fft.warnings) ? fft.warnings : [],
  candidateRates,
  finalRates,
  stabilityBaselineFound: !!previousRates,
  tierCosts: {
    console_fast: psCosts,
    pc: pcCosts,
  },
  fallbackTiers: {
    console_fast: psCosts.filter((row) => row.fallback).map((row) => ({
      targetK: row.targetK,
      fallbackFromTierK: row.fallbackFromTierK,
      fallbackCapacityCoins: row.fallbackCapacityCoins ?? null,
      fallbackProviderPriceEurPer100K:
        row.fallbackProviderPriceEurPer100K ?? null,
      rawUsdPerM: row.rawUsdPerM,
      source: row.selectedSource,
    })),
    pc: pcCosts.filter((row) => row.fallback).map((row) => ({
      targetK: row.targetK,
      fallbackFromTierK: row.fallbackFromTierK,
      fallbackCapacityCoins: row.fallbackCapacityCoins ?? null,
      fallbackProviderPriceEurPer100K:
        row.fallbackProviderPriceEurPer100K ?? null,
      rawUsdPerM: row.rawUsdPerM,
      source: row.selectedSource,
    })),
  },
};

const snapshot = {
  schemaVersion: 1,
  eventId: config.eventId,
  runId: config.runId,
  generatedAt: new Date().toISOString().replace(/\.(\d{3})Z$/, '.$1000Z'),
  mode: settings.mode,
  serviceType: 'coins',
  legalRanges: settings.legalRanges,
  rules,
  observations: {
    source: 'fft+utt-v2',
    ratioEuroUsd,
    cyclePSUsdPerM: Number(fft.cycle.ps.usdPerM),
    cyclePCUsdPerM: positiveNumber(fft.cycle.pc?.usdPerM),
    riskLevel: settings.probe.transferRiskLevel,
    tierCosts: pricingAudit.tierCosts,
    fallbackTiers: pricingAudit.fallbackTiers,
  },
};

return [{
  json: {
    valid: true,
    failureReason: null,
    snapshot,
    pricingAudit,
  },
}];

/* eslint-disable */
const startedAt = Date.now();
const item = $input.first().json;
const snapshot = item?.snapshot;

// Validation failures stop the run through the Error Trigger. The snapshot has
// not been signed or sent, so production pricing is untouched.
function fail(reason) {
  throw new Error(
    `Coins pricing snapshot rejected: ${reason} ` +
    `(runId ${snapshot?.runId ?? item?.runId ?? 'unknown'})`,
  );
}

function isPlainObject(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function exactKeys(value, expected) {
  if (!isPlainObject(value)) return false;

  const keys = Object.keys(value);
  if (keys.length !== expected.length) return false;

  const allowed = new Set(expected);
  return keys.every((key) => allowed.has(key));
}

function roundHalfUpBigInt(numerator, denominator) {
  const quotient = numerator / denominator;
  const remainder = numerator % denominator;
  const half = denominator / 2n + (denominator % 2n);
  return remainder >= half ? quotient + 1n : quotient;
}


function roundToDisplayGrain(halalah) {
  return Number(roundHalfUpBigInt(BigInt(halalah), 10n)) * 10;
}

if (!item?.valid || !snapshot) {
  return fail(item?.failureReason || 'Snapshot was not built');
}

const groups = ['console_normal', 'console_fast', 'pc'];

if (!exactKeys(snapshot.rules, groups)) {
  return fail('Snapshot must contain exactly three pricing groups');
}

if (!isPlainObject(snapshot.legalRanges)) {
  return fail('Snapshot legal ranges are missing or invalid');
}

// Mirrors Laravel's CoinsMultiplierCurve: linear interpolation between the two
// bracketing anchors, clamping outside the published range.
//
// Above 2M this follows the curve rather than carrying console_normal's 2M
// terminal multiplier forward, so a normal-derived fast floor can sit up to
// 3.45% higher than the previous workflow produced. Laravel agrees, because it
// interpolates the same anchors.
function multiplierFor(rule, quantity) {
  const anchors = Object.entries(rule.multiplier_anchors_basis_points)
    .map(([coins, bps]) => [Number(coins), Number(bps)])
    .sort((left, right) => left[0] - right[0]);

  if (anchors.length < 2) {
    return null;
  }

  if (quantity <= anchors[0][0]) {
    return anchors[0][1];
  }

  const last = anchors[anchors.length - 1];
  if (quantity >= last[0]) {
    return last[1];
  }

  for (let index = 1; index < anchors.length; index += 1) {
    const [rightCoins, rightBps] = anchors[index];
    if (quantity > rightCoins) continue;

    const [leftCoins, leftBps] = anchors[index - 1];
    const progress = (quantity - leftCoins) / (rightCoins - leftCoins);

    return Math.round(leftBps + (rightBps - leftBps) * progress);
  }

  return null;
}

function tierRate(rule, quantity) {
  if (rule.group === 'console_normal') {
    return rule.flat_rate_halalah_per_million;
  }

  for (let index = 0; index < rule.tier_upper_bounds_k.length; index += 1) {
    if (quantity <= rule.tier_upper_bounds_k[index] * 1_000) {
      return rule.tier_rates_halalah_per_million[index];
    }
  }

  return rule.tier_rates_halalah_per_million[5];
}

function formulaSar(rule, quantity) {
  const rate = tierRate(rule, quantity);
  const multiplier = multiplierFor(rule, quantity);

  if (!Number.isInteger(multiplier) || multiplier <= 0) {
    return null;
  }

  const rateNumerator =
    BigInt(quantity) *
    BigInt(rate) *
    BigInt(multiplier);

  const feeGap = Math.max(0, 1_000_000 - quantity);
  const feeNumerator =
    BigInt(rule.service_fee_halalah) *
    BigInt(feeGap) *
    10_000n;

  const denominator =
    1_000_000n *
    BigInt(rule.discount_divisor_basis_points);

  return Math.max(
    roundToDisplayGrain(
      Number(
        roundHalfUpBigInt(
          rateNumerator + feeNumerator,
          denominator,
        ),
      ),
    ),
    100,
  );
}

function displayedSar(group, quantity) {
  const rule = snapshot.rules[group];
  const override = rule.exact_overrides_halalah[String(quantity)];

  if (Number.isInteger(override) && override > 0) {
    return override;
  }

  const base = formulaSar(rule, quantity);
  if (!Number.isInteger(base) || base <= 0) {
    return null;
  }

  if (group !== 'console_fast') {
    return base;
  }

  const normal = formulaSar(snapshot.rules.console_normal, quantity);
  if (!Number.isInteger(normal) || normal <= 0) {
    return null;
  }

  return Math.max(
    base,
    // Laravel reduces to the 0.1-SAR grain BEFORE applying 105%.
    // See CoinsPriceCalculator::percentageFloor().
    Number(
      roundHalfUpBigInt(
        (BigInt(normal) / 10n) * 105n,
        100n,
      ),
    ) * 10,
    roundToDisplayGrain(
      Number(
        roundHalfUpBigInt(
          BigInt(normal) * 1_000_000n +
            BigInt(quantity) * 500n,
          1_000_000n,
        ),
      ),
    ),
    normal + 100,
  );
}

let pricesChecked = 0;

for (const group of groups) {
  const rule = snapshot.rules[group];

  const rateKey = group === 'console_normal'
    ? 'flat_rate_halalah_per_million'
    : 'tier_rates_halalah_per_million';

  const expectedKeys = [
    'version',
    'group',
    'tier_upper_bounds_k',
    rateKey,
    'multiplier_anchors_basis_points',
    'service_fee_halalah',
    'discount_divisor_basis_points',
    'exact_overrides_halalah',
  ];

  if (!exactKeys(rule, expectedKeys)) {
    return fail(`${group} has unsupported or missing rule fields`);
  }

  if (rule.version !== 1 || rule.group !== group) {
    return fail(`${group} rule identity is invalid`);
  }

  if (
    !Array.isArray(rule.tier_upper_bounds_k) ||
    rule.tier_upper_bounds_k.length !== 5 ||
    rule.tier_upper_bounds_k.some((value, index, values) =>
      !Number.isInteger(value) ||
      value <= 0 ||
      (index > 0 && value <= values[index - 1]),
    )
  ) {
    return fail(`${group} tier bounds are invalid`);
  }

  if (!isPlainObject(rule.multiplier_anchors_basis_points)) {
    return fail(`${group} multiplier anchor table is invalid`);
  }

  const anchorQuantities = Object.keys(rule.multiplier_anchors_basis_points);

  if (anchorQuantities.length < 2) {
    return fail(`${group} needs at least two multiplier anchors`);
  }

  for (const [quantity, bps] of Object.entries(
    rule.multiplier_anchors_basis_points,
  )) {
    if (
      !/^\d+$/.test(quantity) ||
      Number(quantity) <= 0 ||
      !Number.isInteger(bps) ||
      bps <= 0
    ) {
      return fail(`${group} multiplier anchor ${quantity} is invalid`);
    }
  }

  if (
    !Number.isInteger(rule.service_fee_halalah) ||
    rule.service_fee_halalah < 0
  ) {
    return fail(`${group} small-order fee is invalid`);
  }

  if (
    !Number.isInteger(rule.discount_divisor_basis_points) ||
    rule.discount_divisor_basis_points <= 0
  ) {
    return fail(`${group} discount divisor is invalid`);
  }

  if (!isPlainObject(rule.exact_overrides_halalah)) {
    return fail(`${group} exact override map is invalid`);
  }

  for (const [quantity, value] of Object.entries(
    rule.exact_overrides_halalah,
  )) {
    if (
      !/^\d+$/.test(quantity) ||
      !Number.isInteger(value) ||
      value < 10 ||
      value % 10 !== 0
    ) {
      return fail(`${group} exact override is invalid`);
    }
  }

  if (group === 'console_normal') {
    if (
      !Number.isInteger(rule.flat_rate_halalah_per_million) ||
      rule.flat_rate_halalah_per_million <= 0
    ) {
      return fail('Normal group rate is invalid');
    }
  } else if (
    !Array.isArray(rule.tier_rates_halalah_per_million) ||
    rule.tier_rates_halalah_per_million.length !== 6 ||
    rule.tier_rates_halalah_per_million.some(
      (rate) => !Number.isInteger(rate) || rate <= 0,
    )
  ) {
    return fail(`${group} must contain six positive tier rates`);
  }

  const range = snapshot.legalRanges[group];

  if (
    !isPlainObject(range) ||
    !Number.isInteger(range.minimum) ||
    !Number.isInteger(range.maximum) ||
    !Number.isInteger(range.increment) ||
    range.minimum <= 0 ||
    range.maximum < range.minimum ||
    range.increment <= 0 ||
    (range.maximum - range.minimum) % range.increment !== 0
  ) {
    return fail(`${group} legal range is invalid`);
  }

  // An anchor table has no expected length - that check belonged to the
  // expansion. What matters is that the last anchor reaches the maximum, since
  // Laravel clamps above it and would otherwise price a 20M order at the rate
  // of whatever the table stopped at.
  const highestAnchor = Math.max(
    ...Object.keys(rule.multiplier_anchors_basis_points).map(Number),
  );

  if (highestAnchor < range.maximum) {
    return fail(
      `${group} multiplier anchors stop at ${highestAnchor}, below the ${range.maximum} maximum`,
    );
  }

  let previous = null;

  for (
    let quantity = range.minimum;
    quantity <= range.maximum;
    quantity += range.increment
  ) {
    const multiplier = multiplierFor(rule, quantity);

    if (!Number.isInteger(multiplier) || multiplier <= 0) {
      return fail(`${group} has no multiplier for ${quantity}`);
    }

    const total = displayedSar(group, quantity);

    if (!Number.isInteger(total) || total <= 0) {
      return fail(`${group} generated an invalid price at ${quantity}`);
    }

    if (previous !== null && total < previous) {
      return fail(
        `${group} price descends at ${quantity}: ${total} < ${previous}`,
      );
    }

    previous = total;
    pricesChecked += 1;
  }
}

// Deliberately restated rather than read from Config: this is the guard that
// catches a Prepare bug that mangles legalRanges on the way through. It has to
// be kept in step with Config by hand, and with the live Coins rounding unit.
const expectedRanges = {
  console_normal: {
    minimum: 50_000,
    maximum: 2_000_000,
    increment: 5_000,
  },
  console_fast: {
    minimum: 50_000,
    maximum: 20_000_000,
    increment: 5_000,
  },
  pc: {
    minimum: 50_000,
    maximum: 20_000_000,
    increment: 5_000,
  },
};

for (const group of groups) {
  if (!exactKeys(snapshot.legalRanges[group], [
    'minimum',
    'maximum',
    'increment',
  ])) {
    return fail(`${group} legal range fields are invalid`);
  }

  for (const key of ['minimum', 'maximum', 'increment']) {
    if (
      snapshot.legalRanges[group][key] !==
      expectedRanges[group][key]
    ) {
      return fail(
        'Coins legal ranges do not match the active storefront contract',
      );
    }
  }
}

if (Number(snapshot.observations?.riskLevel) !== 10) {
  return fail('Transfer risk level must be 10');
}

return [{
  json: {
    valid: true,
    failureReason: null,
    coinsPricingSnapshot: snapshot,
    pricingAudit: item.pricingAudit ?? null,
    validationSummary: {
      groups: groups.length,
      pricesChecked,
      fullScheduleChecked: true,
      durationMs: Date.now() - startedAt,
      exactOverrideCounts: Object.fromEntries(
        groups.map((group) => [
          group,
          Object.keys(
            snapshot.rules[group].exact_overrides_halalah,
          ).length,
        ]),
      ),
    },
  },
}];

/* eslint-disable */
// The approved branch arrives carrying the Telegram response, not the
// snapshot, so read the snapshot from its own node instead of from $input.
const item = $('Assess Price Move').first().json;
if (!item.valid || !item.coinsPricingSnapshot) {
  throw new Error(
    `Cannot sign an invalid Coins pricing snapshot: ${item.failureReason || 'none was built'}`,
  );
}

// This node is the single gate in front of Laravel, so the approval is checked
// here rather than in a branch. On the approved path $input carries the
// Telegram answer; on the direct path no approval was required at all.
if (item.approvalRequired) {
  const approval = $input.first().json;
  if (approval?.data?.approved !== true) {
    throw new Error(
      'The proposed Coins pricing was not approved on Telegram ' +
      `(runId ${item.coinsPricingSnapshot.runId}). No pricing rules were changed.`,
    );
  }
}

const secret = $env.N8N_PRICING_SECRET;
if (!secret) {
  throw new Error('N8N_PRICING_SECRET is not configured on the n8n host.');
}

// Laravel rejects any snapshot whose generatedAt is more than 300 seconds old
// (CoinsPricingRunRequest::validateGeneratedAt). generatedAt is minted in
// Prepare Coins Snapshot, BEFORE the Telegram approval wait, so any answer
// slower than five minutes used to be rejected at publish no matter what the
// owner chose. Re-stamp it here - this node runs after approval - so the
// freshness window covers sign to publish instead of probe to publish. The
// observations themselves can be up to the approval wait old; that is the
// deliberate cost of asking a human.
const snapshot = {
  ...item.coinsPricingSnapshot,
  generatedAt: new Date().toISOString().replace(/\.(\d{3})Z$/, '.$1000Z'),
};

const crypto = require('crypto');
const timestamp = String(Math.floor(Date.now() / 1000));
const event = snapshot.eventId;
const rawBody = JSON.stringify(snapshot);
const signingInput = `${timestamp}\n${event}\n${rawBody}`;
const signature = crypto
  .createHmac('sha256', secret)
  .update(signingInput)
  .digest('hex');

return [{
  json: {
    ...item,
    coinsPricingSnapshot: snapshot,
    signed: true,
    timestamp,
    event,
    rawBody,
    signature,
  },
}];

/* eslint-disable */
const response = $input.first().json;
let body = response.body ?? response.data ?? response;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch {}
}

const statusCode = Number(response.statusCode || 0);
const expectedRunId = $('Sign Pricing Payload').first().json.coinsPricingSnapshot.runId;
const data = body?.data ?? body;
const replayCode = body?.error?.code ?? null;
const replayConfirmed =
  statusCode === 409 &&
  ['coins_pricing_run_replayed', 'coins_pricing_event_replayed'].includes(replayCode);
const appliedConfirmed =
  !response.error &&
  !response.errorMessage &&
  (statusCode === 201 || statusCode === 200) &&
  data &&
  data.runId === expectedRunId &&
  data.status === 'applied';
const publishOk = appliedConfirmed || replayConfirmed;

const signed = $('Sign Pricing Payload').first().json;

if (!publishOk) {
  // The publish node uses neverError, so a rejection arrives here as data. A
  // timeout is genuinely ambiguous: Laravel may have committed the run.
  throw new Error(
    `Laravel did not confirm the Coins pricing run (HTTP ${statusCode || 'unknown'}, ` +
    `runId ${expectedRunId}). ` +
    (statusCode === 0
      ? 'The request never completed, so the outcome is UNKNOWN - verify the PriceRun in Laravel before re-running.'
      : 'No pricing rules were changed.'),
  );
}

{
  const globalData = $getWorkflowStaticData('global');
  const current = globalData.coinsPricingV2 ?? {};
  const rules = signed.coinsPricingSnapshot.rules;
  globalData.coinsPricingV2 = {
    ...current,
    lastSuccessfulAt: new Date().toISOString(),
    lastSuccessfulRunId: expectedRunId,
    lastSuccessfulRates: {
      console_normal: rules.console_normal.flat_rate_halalah_per_million,
      console_fast: [...rules.console_fast.tier_rates_halalah_per_million],
      pc: [...rules.pc.tier_rates_halalah_per_million],
    },
  };
}

return [{
  json: {
    publishOk: true,
    failureReason: null,
    publishResponse: body,
    publishConfirmation: replayConfirmed ? 'replayed_after_retry' : 'applied',
    runId: expectedRunId,
    eventId: signed.coinsPricingSnapshot.eventId,
  },
}];

/* eslint-disable */
const result = $('Evaluate Publish Result').first().json;
const signed = $('Sign Pricing Payload').first().json;
const snapshot = signed.coinsPricingSnapshot;
const rules = snapshot.rules;

return [{
  json: {
    status: 'published',
    runId: snapshot.runId,
    eventId: snapshot.eventId,
    generatedAt: snapshot.generatedAt,
    publishResponse: result.publishResponse,
    publishConfirmation: result.publishConfirmation,
    rates: {
      console_normal:
        rules.console_normal.flat_rate_halalah_per_million,
      console_fast: [
        ...rules.console_fast.tier_rates_halalah_per_million,
      ],
      pc: [
        ...rules.pc.tier_rates_halalah_per_million,
      ],
    },
    pricingAudit: signed.pricingAudit,
    validationSummary: signed.validationSummary,
  },
}];

/* eslint-disable */
// Owner rule: there is no automatic ceiling on a price move - the provider
// quotes its live book, so a big move is a real move. What a big move buys is
// a human look, not a cap. A move needs approval only when it is BOTH large in
// percent AND large in riyals, so ordinary churn never interrupts anyone.
const APPROVAL_MIN_MOVE_FRACTION = 0.25;   // > 25%
const APPROVAL_MIN_MOVE_HALALAH = 1_000;   // AND > 10.00 SAR

const item = $input.first().json;
const snapshot = item.coinsPricingSnapshot;
const rules = snapshot.rules;

const globalData = $getWorkflowStaticData('global');
const previous = globalData.coinsPricingV2?.lastSuccessfulRates ?? null;

const current = {
  console_normal: rules.console_normal.flat_rate_halalah_per_million,
  console_fast: [...rules.console_fast.tier_rates_halalah_per_million],
  pc: [...rules.pc.tier_rates_halalah_per_million],
};

// A rate in halalah per million IS the displayed price at exactly 1,000,000
// coins: the multiplier anchor there is 10,000 bps and the small-order fee gap
// is zero. So a halalah delta reads directly as the riyal delta on the 1M row.
const TIER_LABELS = ['1M', '2M', '5M', '10M', '15M', '20M'];
const moves = [];

function compare(label, previousRate, currentRate) {
  if (!Number.isInteger(previousRate) || previousRate <= 0) return;

  const delta = currentRate - previousRate;
  const magnitude = Math.abs(delta);

  moves.push({
    label,
    previousSar: previousRate / 100,
    currentSar: currentRate / 100,
    deltaSar: Math.round(magnitude) / 100,
    deltaPct: Math.round((delta / previousRate) * 1_000) / 10,
    large:
      magnitude / previousRate > APPROVAL_MIN_MOVE_FRACTION &&
      magnitude > APPROVAL_MIN_MOVE_HALALAH,
  });
}

compare('عادي', previous?.console_normal, current.console_normal);
for (const group of ['console_fast', 'pc']) {
  const name = group === 'console_fast' ? 'سريع' : 'PC';
  current[group].forEach((rate, index) => {
    compare(`${name} ${TIER_LABELS[index] ?? index}`, previous?.[group]?.[index], rate);
  });
}

const largeMoves = moves.filter((move) => move.large);

// With no baseline there is nothing to compare against, so there is no move to
// judge. Publishing is the only way a baseline ever gets written.
const baselineFound = !!previous;
const approvalRequired = baselineFound && largeMoves.length > 0;

// The storefront quotes at a 0.1-SAR grain, so quote the same number here.
const displayed = (halalah) => (Math.round(halalah / 10) * 10 / 100).toFixed(2);

const lines = largeMoves
  .sort((left, right) => Math.abs(right.deltaPct) - Math.abs(left.deltaPct))
  .map((move) =>
    `${move.label}: من ${move.previousSar.toFixed(2)} لـ ${move.currentSar.toFixed(2)} ريال ` +
    `(${move.deltaPct > 0 ? '+' : ''}${move.deltaPct}%، ${move.deltaSar.toFixed(2)} ريال)`,
  );

const telegramMessage = [
  'تسعير الكوينز — حركة كبيرة محتاجة اعتماد',
  '',
  `${largeMoves.length} من ${moves.length} شريحة تحركت أكتر من 25% وأكتر من 10 ريال:`,
  '',
  ...lines,
  '',
  `أسعار المليون: عادي ${displayed(current.console_normal)} | ` +
  `سريع ${displayed(current.console_fast[0])} | ` +
  `PC ${displayed(current.pc[0])} ريال`,
  '',
  `runId: ${snapshot.runId}`,
  'مفيش سعر هيتغير قبل ما تعتمد.',
].join('\n');

return [{
  json: {
    ...item,
    approvalRequired,
    baselineFound,
    priceMove: {
      thresholdFraction: APPROVAL_MIN_MOVE_FRACTION,
      thresholdHalalah: APPROVAL_MIN_MOVE_HALALAH,
      comparedCount: moves.length,
      largeCount: largeMoves.length,
      moves,
    },
    telegramMessage,
  },
}];

/* eslint-disable */
const event = $input.first().json;
const execution = event.execution ?? {};
const error = execution.error ?? {};

const lines = [
  'تسعير الكوينز وقف. مفيش أي سعر اتغير.',
  '',
  `السبب: ${error.message || 'خطأ غير معروف'}`,
];

if (execution.lastNodeExecuted) {
  lines.push(`عند النود: ${execution.lastNodeExecuted}`);
}
if (execution.url) {
  lines.push('', execution.url);
}

// Deliberately no throw here. This code runs inside the error execution, so a
// throw would only bury the original failure. An empty chat id makes the
// Telegram node itself go red, which stays visible in the executions list.
return [{
  json: {
    to: $env.OPS_TELEGRAM_CHAT_ID || '',
    body: lines.join('\n'),
    failureReason: error.message || null,
  },
}];
